//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::nat::write_decimal`; the
//! native twin is `benches/native/Bench/NatWriteDecimal.lean`.
//! values of 2^62 or so, so Nat.repr takes lean_string_of_usize, never the shared strings below
//! 128; the Rust twin formats on the stack and makes one new string object

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::nat;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let mut b = StackBuf::new();
            let _ = nat::write_decimal(&nat_arg(nat_box(x >> 1)), &mut b);
            make_ascii_string(b.as_bytes()).byte_size()
        });
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
